        val HISTORICAL_STATE_AUTHORITY: String? = null
        const val INCLUDE_IN_HOST_COMPARISON = false
        const val INCLUDE_IN_IDENTITY_PARITY = true
        const val INCLUDE_IN_PHASE_B = true
        const val INCLUDE_IN_PROTECTED_HISTORY = false
        const val IS_CURRENT_VERSION = true
    }

    /** Registry projections, resolved by predicate and rendered in projection order. */
    object Projections {
        /** a catalogue of everything declared. It matches every run, so it cannot answer 'is any run orphaned' and is excluded from coverage. */
        val allDeclaredRuns: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11", "D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE", "D11", "V11_SMOKE")
        const val ALL_DECLARED_RUNS_SEMANTICS = "ordered"
        /** exactly one official device run belongs to this version */
        val currentDeviceOfficialRun: List<String> = listOf("D11")
        const val CURRENT_DEVICE_OFFICIAL_RUN_SEMANTICS = "singleton"
        /** exactly one host run belongs to this version */
        val currentHostRun: List<String> = listOf("K11")
        const val CURRENT_HOST_RUN_SEMANTICS = "singleton"
        /** exactly one smoke belongs to this version */
        val currentSmokeRun: List<String> = listOf("V11_SMOKE")
        const val CURRENT_SMOKE_RUN_SEMANTICS = "singleton"
        /** everything this version owns */
        val currentVersionRuns: List<String> = listOf("K11", "D11", "V11_SMOKE")
        const val CURRENT_VERSION_RUNS_SEMANTICS = "ordered"
        /** every official device run identity ever declared */
        val deviceOfficialRuns: List<String> = listOf("D7", "D8", "D9", "D10", "D11")
        const val DEVICE_OFFICIAL_RUNS_SEMANTICS = "ordered"
        /** every device smoke identity ever declared */
        val deviceSmokeRuns: List<String> = listOf("V7_SMOKE", "V8_SMOKE", "V9_SMOKE", "V10_SMOKE", "V11_SMOKE")
        const val DEVICE_SMOKE_RUNS_SEMANTICS = "ordered"
        /** device identities earlier versions declared and never invoked */
        val historicalDeviceRuns: List<String> = listOf("D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE")
        const val HISTORICAL_DEVICE_RUNS_SEMANTICS = "ordered"
        /** the runs a cross-run comparison must account for, in order */
        val hostComparisonRuns: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11")
        const val HOST_COMPARISON_RUNS_SEMANTICS = "ordered"
        /** the canonical host order a comparison iterates */
        val hostRunOrder: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11")
        const val HOST_RUN_ORDER_SEMANTICS = "ordered"
        /** every run whose identity must agree across registry, runner and contract */
        val identityParityRuns: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11", "D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE", "D11", "V11_SMOKE")
        const val IDENTITY_PARITY_RUNS_SEMANTICS = "ordered"
        /** the runs a device phase must carry */
        val phaseBRuns: List<String> = listOf("D11", "V11_SMOKE")
        const val PHASE_B_RUNS_SEMANTICS = "ordered"
        /** runs belonging to v1 through v10, which v11 reads and never writes */
        val protectedHistoricalRuns: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE")
        const val PROTECTED_HISTORICAL_RUNS_SEMANTICS = "ordered"
        /** runs whose state is a matter of record rather than of files present now */
        val runsWithHistoricalStateAuthority: List<String> = listOf("K7", "D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE")
        const val RUNS_WITH_HISTORICAL_STATE_AUTHORITY_SEMANTICS = "ordered"

        /** Every projection by id, so a test can iterate rather than name them. */
        val byId: Map<String, List<String>> = mapOf(
            "all_declared_runs" to allDeclaredRuns,
            "current_device_official_run" to currentDeviceOfficialRun,
            "current_host_run" to currentHostRun,
            "current_smoke_run" to currentSmokeRun,
            "current_version_runs" to currentVersionRuns,
            "device_official_runs" to deviceOfficialRuns,
            "device_smoke_runs" to deviceSmokeRuns,
            "historical_device_runs" to historicalDeviceRuns,
            "host_comparison_runs" to hostComparisonRuns,
            "host_run_order" to hostRunOrder,
            "identity_parity_runs" to identityParityRuns,
            "phase_b_runs" to phaseBRuns,
            "protected_historical_runs" to protectedHistoricalRuns,
            "runs_with_historical_state_authority" to runsWithHistoricalStateAuthority,
        )
    }

    /** Every declared run key, in registry order. */
    val runOrder: List<String> = listOf("K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11", "D7", "V7_SMOKE", "D8", "V8_SMOKE", "D9", "V9_SMOKE", "D10", "V10_SMOKE", "D11", "V11_SMOKE")
}
